use divan::{Bencher, black_box, counter::BytesCount};

use support::regexp::time::TimeParser;

fn main() {
    let parser = TimeParser::new();
    for c in CASES.iter().chain(EXTRA) {
        assert_eq!(
            parser.parse_max_time_seconds(c.text),
            c.expected,
            "case '{}'",
            c.name
        );
    }
    divan::main();
}

struct Case {
    name: &'static str,
    text: &'static str,
    expected: Option<i32>,
}

impl std::fmt::Debug for Case {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.name)
    }
}

const CASES: &[Case] = &[
    Case {
        name: "english_hours",
        text: "After pasta has cooked for approximately 1.5 hours, or until all the water has been absorbed",
        expected: Some(5400),
    },
    Case {
        name: "french_minutes",
        text: "Après que les pâtes aient cuit pendant environ 50 minutes, ou jusqu'à ce que toute l'eau ait été absorbée",
        expected: Some(3000),
    },
    Case {
        name: "german_minutes",
        text: "Nachdem die Nudeln etwa 10 Minuten gekocht haben oder bis das gesamte Wasser absorbiert wurde",
        expected: Some(600),
    },
    Case {
        name: "ukrainian_hours",
        text: "Після того, як макарони варяться приблизно 1.5 години або поки вся вода не вбереться",
        expected: Some(5400),
    },
    Case {
        name: "mandarin_minutes",
        text: "意大利面煮约50分钟后，或直到所有水分都被吸收",
        expected: Some(3000),
    },
    Case {
        name: "japanese_minutes",
        text: "パスタを約10分間茹でた後、または水分がすべて吸収されるまで",
        expected: Some(600),
    },
    Case {
        name: "hindi_minutes",
        text: "पास्ता लगभग 10 मिनटों तक पकने के बाद, या जब तक सारा पानी सोख न लिया जाए",
        expected: Some(600),
    },
];

const EXTRA: &[Case] = &[
    Case {
        name: "multiple_durations",
        text: "fter the dough has been mixed, let it rest on the counter for 15 minutes, then chill it in the fridge for 2 hours, and finally bake it for 45 minutes until it is golden brown.",
        expected: Some(7200),
    },
    Case {
        name: "no_duration",
        text: "Season generously with salt and pepper, then stir until the sauce is smooth and glossy.",
        expected: None,
    },
];

const FILLER: &str =
    "Season generously with salt and pepper, then stir until the sauce is smooth and glossy. ";

#[divan::bench(args = CASES)]
fn parse_by_language(bencher: Bencher, case: &Case) {
    let parser = TimeParser::new();
    bencher
        .counter(BytesCount::new(case.text.len()))
        .bench_local(|| parser.parse_max_time_seconds(black_box(case.text)));
}

#[divan::bench(args = CASES)]
fn detect_lang_only(bencher: Bencher, case: &Case) {
    bencher
        .counter(BytesCount::new(case.text.len()))
        .bench_local(|| whatlang::detect_lang(black_box(case.text)));
}

#[divan::bench(args = EXTRA)]
fn parse_content_shape(bencher: Bencher, case: &Case) {
    let parser = TimeParser::new();
    bencher
        .counter(BytesCount::new(case.text.len()))
        .bench_local(|| parser.parse_max_time_seconds(black_box(case.text)));
}

#[divan::bench(args = [1, 10, 100])]
fn parse_realistic(bencher: Bencher, num_copies: usize) {
    let text = format!("{}Simmer for 20 minutes", FILLER.repeat(num_copies));
    let parser = TimeParser::new();

    assert_eq!(parser.parse_max_time_seconds(&text), Some(1200));

    bencher
        .counter(BytesCount::new(text.len()))
        .bench_local(|| parser.parse_max_time_seconds(black_box(&text)));
}
